using Microsoft.UI.Dispatching;using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;namespace Timarker_WinUI.Pages;public sealed partial class PomodoroPage:Page{private readonly DispatcherQueueTimer _timer;private TimeSpan _left;private bool _running,_break;public PomodoroPage(){InitializeComponent();_timer=DispatcherQueue.CreateTimer();_timer.Interval=TimeSpan.FromSeconds(1);_timer.Tick+=(s,e)=>{if(_left>TotalZero)_left-=TimeSpan.FromSeconds(1);else{_timer.Stop();_running=false;Switch();}Render();};Reset();}private static TimeSpan TotalZero=>TimeSpan.Zero;private void Render(){ClockText.Text=$"{(int)_left.TotalMinutes:00}:{_left.Seconds:00}";StartButton.Content=_running?"暂停":"开始";ModeText.Text=_break?"休息中":"专注中";}private void Start_Click(object s,RoutedEventArgs e){_running=!_running;if(_running)_timer.Start();else _timer.Stop();Render();}private void Reset_Click(object s,RoutedEventArgs e)=>Reset();private void Reset(){_timer.Stop();_running=false;_left=TimeSpan.FromMinutes(_break?BreakBox?.Value??5:FocusBox?.Value??25);Render();}private void Switch_Click(object s,RoutedEventArgs e)=>Switch();private void Switch(){_break=!_break;Reset();}}
